const {
  getProduct,
  getPrice,
  filterByCategory,
  getBasketTotal,
  getStockLabel,
  renderProductCard,
  searchProducts,
} = require("./shop");
const { products } = require("./bodega");

// ---------------------------------------------------------------
// ✅ PROVIDED BY THE BODEGA — these should already pass.
// If they don't, getPrice hasn't been ported over yet.
// ---------------------------------------------------------------

test("provided: getProduct finds a product line", () => {
  expect(getProduct(products, "tortilla").price).toEqual(3.25);
});

test("provided: getPrice tells us a price", () => {
  expect(getPrice(products, "agua")).toEqual(0.75);
  expect(getPrice(products, "caviar")).toEqual(undefined);
});

test("provided: filterByCategory picks a category", () => {
  expect(filterByCategory(products, "snacks").length).toEqual(2);
});

test("provided: getBasketTotal totals a basket", () => {
  expect(getBasketTotal(products, ["tortilla", "agua"])).toEqual(4);
});

// ---------------------------------------------------------------
// 🏷️ Q1a — Stock labels
// ---------------------------------------------------------------

test("Q1a: a full shelf says 'in stock'", () => {
  expect(getStockLabel({ name: "agua", price: 0.75, stock: 24 })).toEqual(
    "in stock",
  );
});

test("Q1a: a nearly-empty shelf warns the customer", () => {
  expect(getStockLabel({ name: "tortilla", price: 3.25, stock: 3 })).toEqual(
    "only 3 left!",
  );
  expect(getStockLabel({ name: "ensaimada", price: 2.25, stock: 1 })).toEqual(
    "only 1 left!",
  );
});

test("Q1a: an empty shelf says SOLD OUT", () => {
  expect(getStockLabel({ name: "churros", price: 2.5, stock: 0 })).toEqual(
    "SOLD OUT",
  );
});

// ---------------------------------------------------------------
// 🖼️ Q1b — The product card
// ---------------------------------------------------------------

test("Q1b: builds the HTML card for a product", () => {
  const agua = {
    name: "agua",
    price: 0.75,
    stock: 24,
    emoji: "💧",
    category: "drinks",
  };
  const html = renderProductCard(agua);
  // toContain works on strings: the card must include all of these
  expect(html).toContain('class="product-card"');
  expect(html).toContain("💧");
  expect(html).toContain("agua");
  expect(html).toContain("€0.75");
  expect(html).toContain('data-name="agua"');
});

test("Q1b: prices always show two decimals", () => {
  const gominolas = {
    name: "gominolas",
    price: 1.0,
    stock: 9,
    emoji: "🍬",
    category: "snacks",
  };
  expect(renderProductCard(gominolas)).toContain("€1.00");
});

test("Q1b: the card uses the stock label from Q1a", () => {
  const churros = {
    name: "churros",
    price: 2.5,
    stock: 0,
    emoji: "🍩",
    category: "food",
  };
  const html = renderProductCard(churros);
  expect(html).toContain("SOLD OUT");
});

// ---------------------------------------------------------------
// 🔍 Q2a — The search engine
// ---------------------------------------------------------------

test("Q2a: finds products by part of their name", () => {
  const results = searchProducts(products, "tort");
  expect(results.length).toEqual(1);
  expect(results[0].name).toEqual("tortilla");
});

test("Q2a: the search ignores CAPITALS", () => {
  const results = searchProducts(products, "HOR");
  expect(results.length).toEqual(1);
  expect(results[0].name).toEqual("horchata");
});

test("Q2a: searching for nothing sells nothing", () => {
  expect(searchProducts(products, "pizza").length).toEqual(0);
});

test("Q2a: the original array stays unchanged", () => {
  const before = products.length;
  searchProducts(products, "tort");
  expect(products.length).toEqual(before);
});

